#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

UNIT_KG = {"kg": Fraction(1), "g": Fraction(1, 1000),
           "lb": Fraction(45359237, 100000000),
           "oz": Fraction(28349523125, 10**12)}
DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
COUNTED = {"delivered", "delivered_late"}
ID_RE = re.compile(r"^\s*SH\D*(\d+)\s*$", re.I)

DELIM = {"east": ",", "lakeside": ",", "west": ";", "harbor": "|", "river": "\t"}
COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "river": {"t", "ref", "shipped", "weight", "status"},
}
WEIGHT_COLS = ("gross", "gross_kg", "weight")
HARBOR_STATE = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", "replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", "replace")
    enc = "utf-8"
    head = b[:2000].decode("latin-1")
    for line in head.split("\n")[:10]:
        m = re.match(r"\s*#\s*charset\s*:\s*(\S+)", line, re.I)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode("utf-8", "replace")


# ---------------------------------------------------------------- values
def norm_status(s):
    return re.sub(r"[\s\-_]+", "_", (s or "").strip().lower())


def norm_type(s):
    s = (s or "").strip().lower()
    if s in ("", "n", "new"):
        return "new"
    if s in ("c", "cor", "corr", "correction", "amend", "cor."):
        return "correction"
    if s in ("v", "void"):
        return "void"
    return "new"


def parse_number(s, comma_decimal=False):
    s = s.strip().replace(" ", "")
    if comma_decimal:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def weight_kg(text, default_unit, comma_decimal=False, unit=None):
    """text may carry its own trailing unit; `unit` is an explicit unit."""
    text = (text or "").strip()
    m = re.match(r"^([-+0-9.,\s]+?)\s*([A-Za-z]+)?$", text)
    if not m:
        raise ValueError(text)
    num, u = m.group(1), m.group(2)
    u = (u or unit or default_unit or "kg").lower()
    return parse_number(num, comma_decimal) * UNIT_KG[u]


MONTHS = {m: i + 1 for i, m in enumerate(
    "jan feb mar apr may jun jul aug sep oct nov dec".split())}


def parse_date(s, form="iso"):
    s = s.strip()
    f = (form or "iso").strip().lower().replace(" ", "")
    if f == "serial" or re.fullmatch(r"\d{5}(\.\d+)?", s):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    if f in ("mm/dd/yyyy", "dd/mm/yyyy"):
        a, b, y = re.split(r"[/.\-]", s)[:3]
        return date(int(y), int(a), int(b)) if f[0] == "m" else date(int(y), int(b), int(a))
    if f in ("dmy", "dd-mm-yyyy", "dd.mm.yyyy"):
        d, m, y = re.split(r"[/.\-]", s)[:3]
        return date(int(y), int(m), int(d))
    if f == "yyyyddd":
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
    if f == "yyyymmdd":
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})", s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    m = re.match(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
    if m:
        return date(*map(int, m.groups()))
    m = re.fullmatch(r"(\d{4})/(\d{1,2})/(\d{1,2})", s)
    if m:
        return date(*map(int, m.groups()))
    raise ValueError(s)


def parse_time_utc(s):
    s = s.strip()
    dt = datetime.fromisoformat(s.replace("Z", "+00:00").replace("z", "+00:00"))
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.date()


def parse_ship(s, form):
    s = s.strip()
    if re.search(r"\d[T ]\d{1,2}:\d{2}", s):
        return parse_time_utc(s)
    return parse_date(s, form)


def ship_month(d):
    return "%04d-%02d" % (d.year, d.month)


# ---------------------------------------------------------------- records
class Rec:
    """Lazy record: calc() returns (counted, month, kg)."""
    __slots__ = ("num", "type", "calc")

    def __init__(self, num, typ, calc=None):
        self.num, self.type, self.calc = num, typ, calc


def mk_num(s):
    m = ID_RE.match(s or "")
    return int(m.group(1)) if m else None


def make_calc(status, shipped_fn, weight_fn):
    def calc():
        if norm_status(status) not in COUNTED:
            return (False, None, None)
        return (True, ship_month(shipped_fn()), weight_fn())
    return calc


# ---- delimited
def logical_lines(text, csv_quoting):
    lines = text.replace("\r\n", "\n").split("\n")
    i = 0
    while i < len(lines):
        ln = lines[i]
        i += 1
        if csv_quoting and not ln.startswith("#"):
            while ln.count('"') % 2 == 1 and i < len(lines):
                ln += "\n" + lines[i]
                i += 1
        yield ln


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    csvq = delim == ","
    seq = None
    direc = {}
    hdr = None
    out = []
    for ln in logical_lines(text, csvq):
        if ln.startswith("#"):
            m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*)$", ln)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).strip().lower())
                val = m.group(2).strip()
                direc[name] = val
                if name == "seq" and seq is None:
                    try:
                        seq = int(val)
                    except ValueError:
                        pass
            else:
                m = re.match(r"#\s*\w+ export seq=(\d+)", ln)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if not ln.strip():
            continue
        if csvq:
            row = next(csv.reader([ln], delimiter=","))
        else:
            row = ln.split(delim)
        cells = [c.strip().lower() for c in row]
        if cells and all(c in cols for c in cells):
            hdr = cells
            continue
        if hdr is None:
            continue
        rowunit = None
        wi = next((hdr.index(c) for c in WEIGHT_COLS if c in hdr), None)
        if len(row) == len(hdr) + 1 and wi is not None and row[wi + 1].strip().lower() in UNIT_KG:
            rowunit = row[wi + 1].strip().lower()
            del row[wi + 1]
        if len(row) < len(hdr):
            row = row + [""] * (len(hdr) - len(row))
        d = dict(zip(hdr, row))
        idv = d.get("id") or d.get("ref") or ""
        num = mk_num(idv)
        if num is None:
            continue  # trailer / total row
        unit_dir = direc.get("unit") or direc.get("weight unit") or ""
        um = re.match(r"([A-Za-z]+)", unit_dir)
        dunit = um.group(1).lower() if um else None
        commadec = "decimal comma" in unit_dir.lower()
        datefm = direc.get("dates") or direc.get("date format")
        typ = norm_type(d.get("type") or d.get("kind") or d.get("typ") or d.get("rec") or d.get("t"))
        if typ == "void":
            out.append(Rec(num, typ))
            continue
        if depot == "harbor":
            status = HARBOR_STATE.get(d.get("state", "").strip().upper(), d.get("state", ""))
            shipped = d.get("date", "")
        else:
            status = d.get("status", "")
            shipped = d.get("shipped", "")
        wtext = d.get("gross") or d.get("gross_kg") or d.get("weight") or ""
        if "gross_kg" in d:
            fixed = "kg"
        else:
            fixed = None
        form = {"east": "YMD", "lakeside": "iso", "west": "DD.MM.YYYY",
                "harbor": "iso", "river": "MM/DD/YYYY"}[depot]
        if datefm:
            form = datefm if not (depot == "west") else form
        unit = rowunit or dunit or "kg"

        def wf(wtext=wtext, unit=unit, commadec=commadec, fixed=fixed):
            if fixed:
                return weight_kg(wtext, fixed, commadec)
            return weight_kg(wtext, unit, commadec)

        out.append(Rec(num, typ, make_calc(status, lambda s=shipped, f=form: parse_ship(s, f), wf)))
    return seq, out


# ---- fixed width
LAYOUTS = {
    "FW1": dict(len=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)),
    "FW2": dict(len=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)),
    "FW3": dict(len=41, id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)),
}
LEN_TO_LAYOUT = {v["len"]: k for k, v in LAYOUTS.items()}


def fw_calc(layout, status, shipped, weight):
    def calc():
        if FW_STATUS.get(status.strip().upper(), "") not in COUNTED:
            return (False, None, None)
        if layout == "FW1":
            d = parse_date(shipped, "YYYYDDD")
            kg = Fraction(int(weight)) * UNIT_KG["g"]
        elif layout == "FW2":
            d = parse_date(shipped, "YYYYMMDD")
            kg = Fraction(int(weight), 100)
        else:
            d = parse_date(shipped, "YYYYDDD")
            kg = Fraction(int(weight), 10) * UNIT_KG["lb"]
        return (True, ship_month(d), kg)
    return calc


def parse_south(text):
    seq = None
    layout = None
    out = []
    for ln in text.replace("\r\n", "\n").split("\n"):
        if "\f" in ln or "SOUTH DEPOT" in ln.upper() and "PAGE" in ln.upper():
            continue
        if ln.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", ln)
            if m:
                layout = m.group(1)
            m = re.match(r"#SEQ\s+(\d+)", ln)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not ln.strip():
            continue
        lay = LEN_TO_LAYOUT.get(len(ln))
        if lay is None:
            if layout in LAYOUTS and len(ln) < LAYOUTS[layout]["len"] and ln[:2] == "SH" or \
               (layout in LAYOUTS and len(ln) < LAYOUTS[layout]["len"] and ln[:3] in ("NSH", "CSH", "VSH")):
                lay = layout
                ln = ln.ljust(LAYOUTS[lay]["len"])
            else:
                continue
        L = LAYOUTS[lay]
        g = lambda k: ln[L[k][0]:L[k][1]]
        num = mk_num(g("id"))
        if num is None:
            continue
        typ = norm_type(g("type"))
        if typ == "void":
            out.append(Rec(num, typ))
        else:
            out.append(Rec(num, typ, fw_calc(lay, g("status"), g("shipped"), g("weight"))))
    return seq, out


# ---- xml
def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if (root.get("seq") or "").strip().isdigit() else None
    runit = root.get("weight-unit")
    out = []
    for sh in root.iter("shipment"):
        def val(name):
            if sh.get(name) is not None:
                return sh.get(name)
            c = sh.find(name)
            return c.text if c is not None and c.text is not None else None
        num = mk_num(sh.get("id") or "")
        if num is None:
            continue
        typ = norm_type(sh.get("type"))
        if typ == "void":
            out.append(Rec(num, typ))
            continue
        w = sh.find("weight")
        if w is not None:
            wtext, wunit = w.text or "", w.get("unit")
        else:
            wtext, wunit = sh.get("weight") or "", sh.get("unit")
        status = val("status") or ""
        shipped = val("shipped") or ""
        out.append(Rec(num, typ, make_calc(
            status, lambda s=shipped: parse_ship(s, "DD Mon YYYY"),
            lambda t=wtext, u=wunit: weight_kg(t, runit, False, u))))
    return seq, out


# ---- jsonl
def parse_json(text):
    seq = None
    out = []
    for ln in text.split("\n"):
        if not ln.strip():
            continue
        try:
            v = json.loads(ln)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                m = o["meta"]
                if seq is None and isinstance(m, dict) and "seq" in m:
                    seq = int(m["seq"])
                continue
            num = mk_num(str(o.get("id", "")))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            if typ == "void":
                out.append(Rec(num, typ))
                continue
            wtext, wunit = None, None
            for k, v2 in o.items():
                if k.lower().startswith("weight_") and k[7:].lower() in UNIT_KG:
                    wtext, wunit = str(v2), k[7:].lower()
                    break
            if wtext is None and "weight" in o:
                wtext, wunit = str(o["weight"]), o.get("unit")
            out.append(Rec(num, typ, make_calc(
                str(o.get("status", "")), lambda s=str(o.get("shipped_at", "")): parse_ship(s, "iso"),
                lambda t=wtext, u=wunit: weight_kg(t, "kg", False, u))))
    return seq, out


# ---------------------------------------------------------------- main
def load(path, depot):
    b = read_bytes(path)
    head = b.lstrip(b"\xef\xbb\xbf\xff\xfe\xfe")[:64]
    if depot == "central" or head[:1] == b"<" or b[:2] in (b"<\x00", b"\x00<") \
            or b.lstrip()[:5] == b"<?xml":
        return parse_xml(b)
    text = decode(b)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_json(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0].lower()
        seq, recs = load(p, depot)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        cur = {}
        for seq, name, recs in sorted(exps, key=lambda e: (e[0], e[1])):
            for r in recs:
                if r.type == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    def rank(d):
        return (DEPOT_ORDER.index(d), "") if d in DEPOT_ORDER else (len(DEPOT_ORDER), d)
    order = sorted(current, key=rank)
    owner = {}
    count = {}
    for d in order:
        for num, r in current[d].items():
            count[num] = count.get(num, 0) + 1
            owner.setdefault(num, (d, r))
    handovers = sum(1 for c in count.values() if c > 1)

    depots = {d: [0, Fraction(0)] for d in sorted(current)}
    months = {}
    for num, (d, r) in owner.items():
        counted, month, kg = r.calc()
        if not counted:
            continue
        depots[d][0] += 1
        depots[d][1] += kg
        m = months.setdefault(month, [0, Fraction(0)])
        m[0] += 1
        m[1] += kg

    def rnd(f):
        return float((Decimal(f.numerator) / Decimal(f.denominator)).quantize(
            Decimal("0.01"), ROUND_HALF_UP)) if False else float(
            (Fraction(f) * 100 + Fraction(1, 2)).__floor__() / 100)

    res = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd(v[1])} for d, v in depots.items()},
        "months": {k: {"shipments": v[0], "total_kg": rnd(months[k][1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(res, f, indent=2)


if __name__ == "__main__":
    main()
